(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.04-t*0.5)*5 + Math.cos((y+w1y)*0.03+t*0.4)*4;
  const w2y = Math.cos((y+w1y)*0.04+t*0.45)*5 + Math.sin((x+w1x)*0.035-t*0.55)*4;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.6],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.0],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.5],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.8],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.11,2.1,0.75],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*60,0.13,1.8,0.65],
    [200+Math.sin(t*0.7+1)*90,220+Math.cos(t*0.3+4)*40,0.05,2.8,0.85]
  ];
  let aS=0,iS=0,crs=0;
  for(let si=0;si<src.length;si++){
    const[sX,sY,f,sp,w]=src[si];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    const ns=src[(si+1)%src.length];
    const d2=Math.sqrt((sx-ns[0])**2+(sy-ns[1])**2);
    crs+=Math.sin(d*f+d2*ns[2]*0.5-t*sp*0.8)*w*0.3;
  }
  const n=src.length,act=aS/n,inh=iS/n,cr=crs/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+t*1.5)*Math.cos(sy*0.06-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const radial=Math.sin(dist*0.08-t*1.8)*Math.cos(ang*2+t*0.3)*0.2;
  const cell=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.08-sy*0.12+t*0.7)*Math.cos(sx*0.1+sy*0.07-t*0.5)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+radial+cr*0.5)*2.2);
  const reaction2=Math.tanh((act*0.5+cr-bg*0.5+spiral*0.8)*1.8);
  const cellMod=Math.tanh(cell*1.5)*0.3;
  const blend=reaction*0.6+cellMod*0.2+reaction2*0.2,v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,88],[18,95,105],[25,150,130],[140,195,100],
    [220,195,60],[230,140,60],[200,85,65],[150,45,75],[80,20,65],[35,15,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.75?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*0.3)*0.1;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
